const isColumnActive = (
  sortable: boolean,
  column: any,
  sortedColumnAccessor: string,
) => sortable && sortedColumnAccessor === column.accessorKey;

export const TableV2: React.FC<TableProps> = ({
  rows,
  columns,
  rowClickHandler,
  initialSorting = "asc",
}): JSX.Element => {
  const [selectedRow, setSelectedRow] = useState(0);
  const [sortConfig, setSortConfig] = useState<{
    [key: string]: "desc" | "asc";
  }>({});
  const [displayedRows, setDisplayedRows] = useState<RowDef<any>[]>(rows);
  const [sortedColumnAccessor, setSortedColumnAccessor] = useState("");

  useEffect(() => {
    setDisplayedRows(rows);
  }, [rows]);

  const sortRows = (
    columnAccessor: string,
    coulmnDirection: "desc" | "asc",
  ) => {
    let sortableItems = [...displayedRows];
    const columnBeingSorted = columns.find(
      (column) => column.accessorKey === columnAccessor,
    );
    const sortAccessor = columnBeingSorted?.sortAccessor;

    sortableItems.sort((a, b) => {
      let aValue = a[columnAccessor];
      let bValue = b[columnAccessor];

      if (sortAccessor) {
        aValue = sortAccessor(a);
        bValue = sortAccessor(b);
      }
      if (
        columnBeingSorted?.sortLevel === "single" ||
        !columnBeingSorted?.sortLevel
      ) {
        if (aValue < bValue) {
          return coulmnDirection === "asc" ? -1 : 1;
        }
        if (aValue > bValue) {
          return coulmnDirection === "asc" ? 1 : -1;
        }
      } else if (columnBeingSorted?.sortLevel === "multi") {
        if (aValue.firstLevel === bValue.firstLevel) {
          if (aValue[columnAccessor] < bValue[columnAccessor]) {
            return coulmnDirection === "asc" ? -1 : 1;
          }
          if (aValue[columnAccessor] > bValue[columnAccessor]) {
            return coulmnDirection === "asc" ? 1 : -1;
          }
        }
      }
      return 0;
    });
    return sortableItems;
  };

  const requestSort = (key: string) => {
    let direction: "asc" | "desc" = initialSorting;
    if (sortConfig && sortConfig[key] === "asc") {
      direction = "desc";
    }
    const sortedItems = sortRows(key, direction);
    setDisplayedRows(sortedItems);
    setSortedColumnAccessor(key);
    setSortConfig((prevState) => ({
      ...prevState,
      [key]: direction,
    }));
  };
  return (
    <>
      <StyledTableV2 className="table-tabs-header">
        <Thead>
          <Tr>
            {columns.map(({ css, sortable, ...column }, index) => (
              <Th
                onClick={
                  sortable
                    ? () => requestSort(column.accessorKey as string)
                    : undefined
                }
                css={{
                  textAlign: "start",
                  ...css,
                }}
                sortable={sortable}
                isActive={isColumnActive(
                  !!sortable,
                  column,
                  sortedColumnAccessor,
                )}
                key={`header-${index}`}
              >
                <Box
                  css={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                  }}
                >
                  {column.header}
                  {sortable &&
                  sortConfig &&
                  sortedColumnAccessor === column.accessorKey ? (
                    sortConfig[column.accessorKey] === "asc" ? (
                      <SortDescIcon />
                    ) : (
                      <SortAscIcon />
                    )
                  ) : sortable ? (
                    <SortDefaultIcon />
                  ) : null}
                </Box>
              </Th>
            ))}
          </Tr>
        </Thead>
      </StyledTableV2>
      <StyledDiv>
        <StyledTableV2
          hoverEffect={!!rowClickHandler}
          className="table-tabs-body"
        >
          <tbody>
            {displayedRows.map((row, rowIndex) => (
              <Tr
                key={`row ${rowIndex}`}
                className={
                  rowClickHandler && selectedRow === rowIndex ? "selected" : ""
                }
                onClick={() => {
                  //selectedRow !== rowIndex is not needed because pointerEvents is none
                  if (rowClickHandler) {
                    rowClickHandler(row);
                    setSelectedRow(rowIndex);
                  }
                }}
              >
                {columns.map((column, cellIndex) => {
                  return (
                    <Td key={`cell ${cellIndex}`} css={{ color: "$light" }}>
                      {row[column.accessorKey]}
                    </Td>
                  );
                })}
              </Tr>
            ))}
          </tbody>
        </StyledTableV2>
      </StyledDiv>
    </>
  );
};

