export const TableContainerWithTabs: React.FC<ContainerProps> = ({
  isLoading,
  tabs,
  tabListCta,
  rowClickHandler,
}) => {
  const defaultTab = tabs ? tabs[0].title : "";

  return (
    <Container
      layout="column"
      alignItems="start"
      className="table-container"
      css={{ p: 0 }}
    >
      {isLoading ? (
        <LoadingContent />
      ) : (
        tabs && (
          <Tabs
            css={{ width: "$full" }}
            className="tabs"
            defaultValue={defaultTab}
          >
            <Flex
              css={{
                justifyContent: "space-between",
                alignItems: "center",
                padding: "$lg",
              }}
            >
              <TabsList
                css={{ backgroundColor: "$bg02" }}
                className="tabs-list"
                aria-label="Table tabs"
              >
                {tabs.map((tab, index) => (
                  <TabsTrigger
                    variant="tableTab"
                    className="tabs-trigger"
                    key={index}
                    value={tab.title}
                    css={
                      tabs.length === 1
                        ? {
                            '&[data-state="active"]': {
                              color: "$textLight",
                              boxShadow: "none",
                            },
                          }
                        : undefined
                    }
                  >
                    {tab.title}
                    {tab.count != null && (
                      <BadgeCount
                        css={{
                          marginLeft: "$xxs",
                          letterSpacing: "normal",
                        }}
                        count={tab.count}
                      />
                    )}
                  </TabsTrigger>
                ))}
              </TabsList>
              {tabListCta}
            </Flex>
            {tabs.map((tab, index) => (
              <TabsContent
                className="tab-content"
                key={index}
                value={tab.title}
              >
                <TableV2
                  {...tab.tableProps}
                  rowClickHandler={rowClickHandler}
                />
              </TabsContent>
            ))}
          </Tabs>
        )
      )}
    </Container>
  );
};
